var t=[{title:`Gewrichten en hoe ze bewegen`,text:`De elleboog werkt vooral als een scharnier en laat buigen en strekken toe. De schouder en heup zijn kogelgewrichten die in meerdere richtingen kunnen bewegen. De wervelkolom heeft veel gewrichten, en hun gecombineerde beweging helpt bij positionering en het doorgeven van belasting. Echte gewrichtsbeweging is nooit helemaal zo eenvoudig als een tekening in een leerboek.`},{title:`Bewegingsbereik (ROM)`,text:`Actieve ROM is het bereik dat je met je eigen spieren kunt halen. Passieve ROM is het bereik dat je met hulp van buiten kunt halen, en dat kan groter zijn. Een beperkt actief bereik kan komen door zwakte, vaardigheid, stijfheid, pijn of een mix daarvan, dus „strakke spieren” zijn niet altijd het hele verhaal. Lichaamsverhoudingen en gewrichtsstructuur bepalen ook hoe diep een oefening comfortabel voelt.`},{title:`Volledige en gedeeltelijke herhalingen`,text:`Een volledige herhaling gebruikt het geplande, veilige bereik voor die oefening. Het betekent niet dat je het gewricht tot zijn anatomische grens forceert. Onderzoek ondersteunt trainen door een volledig bereik dat je kunt beheersen voor kracht in veel situaties, en gedeeltelijke herhalingen kunnen helpen als ze met opzet zijn gepland. Een pijnvrij korter bereik kan een betere keuze zijn dan een diep, pijnlijk bereik.`},{title:`Praktische checks`,text:`Let bij een squat op of je voeten contact houden met de vloer, je romp beheerst blijft en je knieën en heupen comfortabel bewegen. Check bij overhead persen of je armen boven je hoofd komen zonder grote holle rug. Als een beweging onderaan of bovenaan ongecontroleerd wordt, verander dan de diepte, de grip of de oefeningvariant.`},{title:`Je bereik vergroten`,text:`Zoek eerst het bereik dat je kunt beheersen, herhaal het dan betrouwbaar en vergroot het daarna als dat nuttig en comfortabel is. Bereik is één trainingsvariabele naast andere, zoals gewicht, herhalingen en stabiliteit.`},{title:`TrainUp gebruiken`,text:`Als beweging in een lichaamsdeel beperkt is, voeg die dan toe als beperking in Profiel, met notities, zodat het schema oefeningen kiest die passen. TrainUp kan niet zeggen of beperkte beweging een medische oorzaak heeft. Is een beperking pijnlijk en gaat hij niet over, laat hem dan beoordelen door een arts of fysiotherapeut.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Beweegrichtlijnen van de WHO`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9219310/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};